class HeizungsanlageCardEditor extends HTMLElement {
  setConfig(config) {
    this._config = config || {};
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    if (this._form) {
      this._form.hass = hass;
      this._applyLanguage();
    }
  }

  connectedCallback() {
    customElements.whenDefined('ha-form').then(() => this._render());
  }

  _t() {
    const lang = ((this._hass && (this._hass.locale?.language || this._hass.language)) || 'de').toLowerCase();
    return lang.startsWith('de') ? EDITOR_I18N.de : EDITOR_I18N.en;
  }

  _schema(t) {
    const ent = (key, domain) => ({ name: 'e_' + key, selector: { entity: domain ? { domain } : {} } });
    const num = (name, extra) => ({ name, selector: { number: { mode: 'box', step: 1, ...extra } } });
    return [
      {
        type: 'expandable',
        title: t.sections.general,
        expanded: true,
        schema: [
          { name: 'title', selector: { text: {} } },
          { name: 'subtitle', selector: { text: {} } },
          {
            name: 'layout',
            selector: {
              select: {
                mode: 'dropdown',
                options: [
                  { value: 'auto', label: t.layoutOptions.auto },
                  { value: 'wide', label: t.layoutOptions.wide },
                  { value: 'compact', label: t.layoutOptions.compact },
                ],
              },
            },
          },
          { name: 'fit_screen', selector: { boolean: {} } },
          { name: 'screen_offset', selector: { number: { mode: 'box', min: 0, max: 400, step: 1, unit_of_measurement: 'px' } } },
        ],
      },
      {
        type: 'expandable',
        title: t.sections.status,
        schema: [
          ent('outside_temp', 'sensor'),
          ent('frost_protection', 'binary_sensor'),
          ent('burner_hours', 'sensor'),
          ent('burner_starts', 'sensor'),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.boiler,
        schema: [
          ent('burner_active', 'binary_sensor'),
          ent('burner_modulation', 'sensor'),
          ent('boiler_temp', 'sensor'),
          ent('supply_temp', 'sensor'),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.pumps,
        schema: [
          ent('heating_pump', 'binary_sensor'),
          ent('charge_pump', 'binary_sensor'),
          ent('dhw_circ_pump', 'binary_sensor'),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.tank,
        schema: [
          ent('tank_temp', 'sensor'),
          ent('tank_target', ['number', 'sensor']),
          ent('tank_min_target', ['sensor', 'number']),
          ent('tank_max_target', ['sensor', 'number']),
          {
            type: 'grid',
            name: '',
            schema: [
              num('tank_range_min', { min: -50, max: 150, unit_of_measurement: '°C' }),
              num('tank_range_max', { min: -50, max: 150, unit_of_measurement: '°C' }),
            ],
          },
          num('limit_offset', { min: 0, max: 30, step: 0.5, unit_of_measurement: 'K' }),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.settings,
        schema: [
          ent('comfort_temp', ['number', 'sensor']),
          ent('normal_temp', ['number', 'sensor']),
          ent('reduced_temp', ['number', 'sensor']),
          ent('curve_slope', ['number', 'sensor']),
          ent('curve_shift', ['number', 'sensor']),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.water,
        schema: [
          ent('gas_total', 'sensor'),
          ent('gas_today', 'sensor'),
          ent('water_total', 'sensor'),
          ent('water_today', 'sensor'),
          ent('water_flow', 'sensor'),
          ent('water_temp', 'sensor'),
        ],
      },
      {
        type: 'expandable',
        title: t.sections.softener,
        schema: [ent('softener_regeneration'), ent('softener_salt'), ent('softener_remaining')],
      },
    ];
  }

  // Karten-Konfiguration -> flache Formulardaten
  _toData(cfg) {
    const ents = { ...DEFAULTS.entities, ...(cfg.entities || {}) };
    const range = Array.isArray(cfg.tank_range) ? cfg.tank_range : DEFAULTS.tank_range;
    const data = {
      layout: cfg.layout || DEFAULTS.layout,
      fit_screen: cfg.fit_screen !== undefined ? cfg.fit_screen : DEFAULTS.fit_screen,
      screen_offset: cfg.screen_offset !== undefined ? cfg.screen_offset : DEFAULTS.screen_offset,
      title: cfg.title !== undefined ? cfg.title : DEFAULTS.title,
      subtitle: cfg.subtitle !== undefined ? cfg.subtitle : DEFAULTS.subtitle,
      tank_range_min: range[0],
      tank_range_max: range[1],
      limit_offset: cfg.limit_offset !== undefined ? cfg.limit_offset : DEFAULTS.limit_offset,
    };
    Object.keys(DEFAULTS.entities).forEach((k) => {
      data['e_' + k] = ents[k] || '';
    });
    return data;
  }

  // Flache Formulardaten -> schlanke Karten-Konfiguration (nur Abweichungen von den Standardwerten)
  _fromData(d) {
    const cfg = { ...this._config };
    const setOrDrop = (key, val, def) => {
      if (val === undefined || (typeof val === 'number' && isNaN(val)) || val === def) delete cfg[key];
      else cfg[key] = val;
    };
    setOrDrop('layout', d.layout, DEFAULTS.layout);
    setOrDrop('fit_screen', d.fit_screen, DEFAULTS.fit_screen);
    setOrDrop('screen_offset', d.screen_offset, DEFAULTS.screen_offset);
    setOrDrop('title', d.title, DEFAULTS.title);
    setOrDrop('subtitle', d.subtitle, DEFAULTS.subtitle);
    setOrDrop('limit_offset', d.limit_offset, DEFAULTS.limit_offset);
    const lo = Number(d.tank_range_min);
    const hi = Number(d.tank_range_max);
    if (isNaN(lo) || isNaN(hi) || (lo === DEFAULTS.tank_range[0] && hi === DEFAULTS.tank_range[1])) delete cfg.tank_range;
    else cfg.tank_range = [lo, hi];

    const ents = {};
    Object.keys(DEFAULTS.entities).forEach((k) => {
      const val = d['e_' + k] ? d['e_' + k] : null;
      if (val !== DEFAULTS.entities[k]) ents[k] = val; // null = Entität bewusst abgewählt
    });
    if (Object.keys(ents).length) cfg.entities = ents;
    else delete cfg.entities;
    return cfg;
  }

  _applyLanguage() {
    const t = this._t();
    if (!this._form || this._lastT === t) return;
    this._lastT = t;
    this._form.schema = this._schema(t);
    this._form.computeLabel = (s) => t.labels[s.name] || s.name;
    this._form.computeHelper = (s) => t.helpers[s.name] || '';
  }

  _render() {
    if (!this._config || !customElements.get('ha-form')) return;
    if (!this._form) {
      this._form = document.createElement('ha-form');
      this._form.addEventListener('value-changed', (ev) => {
        ev.stopPropagation();
        const config = this._fromData(ev.detail.value);
        this._config = config;
        this.dispatchEvent(new CustomEvent('config-changed', { detail: { config }, bubbles: true, composed: true }));
      });
      this.appendChild(this._form);
    }
    if (this._hass) this._form.hass = this._hass;
    this._applyLanguage();
    this._form.data = this._toData(this._config);
  }
}

